pub fn read() {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
    for (directory, leaf) in [(root.join("../foreign"), "alpha.json"), (root.join("../affected"), "beta.json")] {
        let _ = directory.join(leaf);
        println!("{leaf}");
    }
}
